### Ran Playwright code
```js
await page.evaluate('() => {const NativeWorker=globalThis.Worker;globalThis.__socBrowserWorkerObserved={created:0,results:0,errors:0,fallbacks:0};globalThis.Worker=class extends NativeWorker{constructor(...args){super(...args);__socBrowserWorkerObserved.created++;this.addEventListener(\'message\',()=>__socBrowserWorkerObserved.results++);this.addEventListener(\'error\',()=>__socBrowserWorkerObserved.errors++);}};return {instrumentation:\'browser Worker events only; no gameplay mutation\'};}');
```

